// Geography engines: independent touch panels, locked team submissions and a shared class mission.
function geoFields(item){
 const raw=item.geo||{},kind=raw.kind||'choice',allowed=['choice','order','map','measure','memory','profile','model','budget','explain'];
 if(!allowed.includes(kind))throw Error('Choose a supported Geography challenge.');
 const g={kind,source:String(raw.source||'Teacher-created practice question.')};if(g.source.length>1800)throw Error('Keep each practice source under 1800 characters.');
 if(['choice','memory','profile'].includes(kind)&&(!item.options.length||item.options.length>3))throw Error('Add 1–3 wrong choices for this Geography challenge.');
 if(kind==='order'){const parts=item.answer.split('|').map(x=>x.trim());if(parts.length<2||parts.length>8||parts.some(x=>!x)||new Set(parts).size!==parts.length)throw Error('Use 2–8 different sequence steps, separated by |.');}
 if(['map','memory'].includes(kind)){g.board=raw.board||'town';if(!Object.hasOwn(GEO_BOARDS,g.board))throw Error('Choose a valid Geography map.');if(raw.mapImage)g.mapImage=activityImage(raw.mapImage);if(raw.pins){if(!Array.isArray(raw.pins)||raw.pins.length<2||raw.pins.length>8)throw Error('Use 2–8 map markers.');g.pins=raw.pins.map(p=>{if(!Array.isArray(p)||p.length!==3||typeof p[0]!=='string'||!p[0].trim()||p[0].length>80||p.slice(1).some(n=>!Number.isFinite(n)||n<5||n>95))throw Error('Map markers need a label and x/y percentages from 5 to 95.');return [p[0].trim(),p[1],p[2]];});}const pins=g.pins||GEO_BOARDS[g.board].pins;if(kind==='map'&&!pins.some(p=>p[0]===item.answer))throw Error('The map answer must exactly match one marker label.');if(new Set(pins.map(p=>p[0])).size!==pins.length)throw Error('Use unique map marker labels.');}
 for(const key of ['start','maximum','target'])if(raw[key]!==undefined){if(!Number.isInteger(raw[key])||raw[key]<0||raw[key]>100)throw Error('Model values must be whole numbers from 0 to 100.');g[key]=raw[key];}
 if(kind==='measure'){g.maximum=g.maximum||12;g.start=g.start??1;g.unit=String(raw.unit||'cm').slice(0,20);if(!Number.isInteger(Number(item.answer))||Number(item.answer)<0||Number(item.answer)>g.maximum)throw Error('Measurement answer must be a whole number within the ruler range.');}
 if(kind==='model'){g.start=g.start??10;g.target=g.target??12;g.maximum=g.maximum||10;if(Math.abs(g.target-g.start)>g.maximum)throw Error('The glacier target must be reachable within the accumulation/melt range.');if(Number(item.answer)!==g.target)throw Error('Set the correct answer to the glacier target.');}
 if(kind==='budget'){g.budget=raw.budget??8;g.needs=raw.needs||['Need 1','Need 2','Need 3'];g.offers=raw.offers||[['Project A',3,1],['Project B',3,2],['Project C',2,4],['Distraction',4,0]];if(!Number.isInteger(g.budget)||g.budget<1||g.budget>100||!Array.isArray(g.needs)||g.needs.length!==3||g.needs.some(x=>typeof x!=='string'||!x.trim()||x.length>80)||!Array.isArray(g.offers)||g.offers.length<3||g.offers.length>6)throw Error('Budget games need three short needs, 3–6 projects and 1–100 tokens.');g.offers=g.offers.map(o=>{if(!Array.isArray(o)||o.length!==3||typeof o[0]!=='string'||!o[0].trim()||o[0].length>100||!Number.isInteger(o[1])||o[1]<1||o[1]>100||!Number.isInteger(o[2])||o[2]<0||o[2]>7)throw Error('Check project names, whole-number costs and need coverage.');return [...o];});let possible=false;for(let mask=0;mask<2**g.offers.length;mask++){let cost=0,cover=0;g.offers.forEach((o,i)=>{if(mask&(1<<i)){cost+=o[1];cover|=o[2];}});if(cost<=g.budget&&cover===7)possible=true;}if(!possible)throw Error('The budget must allow a project combination covering all three needs.');}
 return {geo:g};
}
function geoEditor(){document.querySelectorAll('[data-row]').forEach(row=>{
 const q=draft.items[Number(row.dataset.row)];q.geo=q.geo||{kind:'choice',source:''};const g=q.geo;
 const box=document.createElement('div');box.className='geo-editor';box.innerHTML='<label>Challenge type<select data-geo-kind>'+['choice','order','map','measure','memory','profile','model','budget','explain'].map(k=>'<option '+(k===g.kind?'selected':'')+'>'+k+'</option>').join('')+'</select></label><label>Practice source / evidence<textarea data-geo-source rows="4" maxlength="1800">'+esc(g.source)+'</textarea></label>';
 if(['choice','memory','profile'].includes(g.kind))box.innerHTML+='<label>Wrong choices · one per line<textarea data-field="options" rows="2">'+esc(q.options.join('\n'))+'</textarea></label>';
 if(g.kind==='order')box.innerHTML+='<p>Write the correct sequence in the model answer above, using | between 2–8 steps. The game shuffles them.</p>';
 if(g.kind==='explain')box.innerHTML+='<p>Students explain aloud or on their own paper. Reveal the model answer, then the teacher or partner checks the response. No automatic text grading.</p>';
 if(['map','memory'].includes(g.kind)){box.innerHTML+='<label>Map<select data-geo-board>'+Object.entries(GEO_BOARDS).map(([k,b])=>'<option value="'+k+'" '+(k===(g.board||'town')?'selected':'')+'>'+b.name+'</option>').join('')+'</select></label><label>Upload a map image (optional)<input data-geo-upload type="file" accept="image/png,image/jpeg,image/webp"></label><label>Markers: label | x% | y% (5–95)<textarea data-geo-pins rows="5">'+esc((g.pins||GEO_BOARDS[g.board||'town'].pins).map(p=>p.join(' | ')).join('\n'))+'</textarea></label><p>For map tasks, the correct answer must match one marker label. Markers are lettered during play; the answer key appears after submission.</p>'+(g.mapImage?'<img class="geo-editor-map" src="'+g.mapImage+'" alt="Uploaded map preview"><button type="button" data-geo-clear-image>Use built-in map</button>':'');}
 if(['measure','model'].includes(g.kind))box.innerHTML+=['start','maximum',...(g.kind==='model'?['target']:[])].map(k=>'<label>'+k+'<input data-geo-number="'+k+'" type="number" min="0" max="100" value="'+(g[k]??(k==='maximum'?12:k==='target'?12:1))+'"></label>').join('');
 if(g.kind==='budget'){const v={...GEO_BUDGETS[1],...g};box.innerHTML+='<label>Token budget<input data-geo-budget type="number" min="1" max="100" value="'+v.budget+'"></label>'+v.needs.map((n,i)=>'<label>Need '+(i+1)+'<input maxlength="80" data-geo-need="'+i+'" value="'+esc(n)+'"></label>').join('')+v.offers.map((o,i)=>'<div class="geo-offer-edit"><input aria-label="Project '+(i+1)+'" data-geo-offer="'+i+'" value="'+esc(o[0])+'"><input aria-label="Cost '+(i+1)+'" type="number" min="1" max="100" data-geo-cost="'+i+'" value="'+o[1]+'">'+v.needs.map((_,n)=>'<label><input type="checkbox" data-geo-cover="'+i+'" data-need="'+n+'" '+(o[2]&(1<<n)?'checked':'')+'>Need '+(n+1)+'</label>').join('')+'</div>').join('');if(!g.needs)Object.assign(g,v);}
 row.append(box);box.querySelector('[data-geo-kind]').onchange=e=>{q.geo={kind:e.target.value,source:g.source};dirty=true;renderRows();};box.querySelector('[data-geo-source]').oninput=e=>g.source=e.target.value;
 box.querySelector('[data-geo-board]')?.addEventListener('change',e=>{g.board=e.target.value;delete g.pins;dirty=true;renderRows();});box.querySelector('[data-geo-pins]')?.addEventListener('input',e=>{g.pins=e.target.value.split('\n').filter(Boolean).map(line=>{const [label,x,y]=line.split('|');return [label.trim(),Number(x),Number(y)];});});
 box.querySelector('[data-geo-upload]')?.addEventListener('change',async e=>{const owner=draft;try{const image=await actUpload(e.target.files[0]);if(draft!==owner||!draft.items.includes(q))return;g.mapImage=image;dirty=true;renderRows();}catch(err){notify(err.message);}});box.querySelector('[data-geo-clear-image]')?.addEventListener('click',()=>{delete g.mapImage;dirty=true;renderRows();});
 box.querySelectorAll('[data-geo-number]').forEach(e=>e.oninput=()=>g[e.dataset.geoNumber]=Number(e.value));box.querySelector('[data-geo-budget]')?.addEventListener('input',e=>g.budget=Number(e.target.value));box.querySelectorAll('[data-geo-need]').forEach(e=>e.oninput=()=>g.needs[Number(e.dataset.geoNeed)]=e.value);box.querySelectorAll('[data-geo-offer]').forEach(e=>e.oninput=()=>g.offers[Number(e.dataset.geoOffer)][0]=e.value);box.querySelectorAll('[data-geo-cost]').forEach(e=>e.oninput=()=>g.offers[Number(e.dataset.geoCost)][1]=Number(e.value));box.querySelectorAll('[data-geo-cover]').forEach(e=>e.onchange=()=>{const o=g.offers[Number(e.dataset.geoCover)],bit=1<<Number(e.dataset.need);o[2]=e.checked?o[2]|bit:o[2]&~bit;dirty=true;});
 });}
function geoLane(name){return {name,index:0,score:0,correct:0,phase:'question',selected:[],history:[],reveal:false};}
function geoRound(l){const q=game.items[l.index];l.phase='question';l.selected=[];l.reveal=false;l.good=null;l.choices=shuffle([q.answer,...q.options]);l.tiles=shuffle(q.answer.split('|').map((text,id)=>({text:text.trim(),id})));l.value=q.geo.start??1;l.gain=0;l.melt=0;l.ran=false;l.studied=false;}
function geoInit(){const mode=FORMATS[game.lesson.format].mode,names=mode==='DUEL'?[game.lesson.settings.teamOne,game.lesson.settings.teamTwo]:mode==='TEAM'?game.lesson.settings.teamNames:[mode==='CLASS'?'Our class':'Explorer'];game.session={engine:'activities',geography:true,mode,lanes:names.map(geoLane),active:0,round:0,review:false,phase:'question',groups:[],exitOpen:false};game.session.lanes.forEach(geoRound);}
function geoButton(i,a,label,extras='',disabled=false){return '<button data-mode-action="geo-'+a+'" data-lane="'+i+'" '+extras+' '+(disabled?'disabled':'')+'>'+label+'</button>';}
function geoBackdrop(type){const base='<rect width="600" height="330" fill="#d9f0f4"/>';let body='';if(type==='town')body='<path d="M60 0 Q140 90 80 160 T120 330" stroke="#55aacc" stroke-width="38" fill="none"/><rect x="235" y="100" width="100" height="80" rx="10" fill="#e7a76c"/><rect x="410" y="100" width="120" height="80" fill="#89bd75"/><path d="M0 265 H600" stroke="#a3aebd" stroke-width="35"/><text x="283" y="146">🏫</text><text x="462" y="146">⚽</text>';
 if(type==='grid'){body='<rect width="600" height="330" fill="#edf3d9"/>';for(let n=0;n<=6;n++)body+='<path d="M'+n*100+' 0 V330 M0 '+n*55+' H600" stroke="#83996c"/>';for(let n=0;n<6;n++)body+='<text x="'+(n*100+40)+'" y="322" font-size="26">'+(20+n)+'</text><text x="2" y="'+(330-n*55-10)+'" font-size="16">'+(40+n)+'</text>';}
 if(type==='world')body='<path d="M300 0 V330 M0 165 H600" stroke="#6b7cbd" stroke-width="3" stroke-dasharray="8 5"/><text x="306" y="22" font-size="16">0° longitude</text><text x="8" y="160" font-size="16">Equator 0°</text><text x="125" y="24">W</text><text x="475" y="24">E</text>';
 if(type==='uk')body='<path d="M300 25 l70 10-25 40 30 35-35 40 40 20 5 60 80 50-90 35-80-30-35-40-35-5 20-50 20-30-10-35-15-25z M80 130 l65-20 25 35-25 20-50-10z" fill="#a8c88f" stroke="#608968" stroke-width="3"/>';
 if(type==='africa')body='<path d="M170 25 L330 18 390 55 410 105 463 125 415 155 385 200 330 290 285 310 253 250 248 183 190 155 145 110z" fill="#e7ca83" stroke="#ac975c" stroke-width="3"/><path d="M0 160 H600" stroke="#c6796c" stroke-dasharray="8 5"/><text x="8" y="154" font-size="16">Equator</text>';
 if(type==='kenya')body='<path d="M180 50 L350 45 435 110 365 255 285 290 180 200 155 100z" fill="#e4c886" stroke="#ac975c" stroke-width="4"/><text x="250" y="150" font-size="30">KENYA</text><path d="M0 160 H600" stroke="#c6796c" stroke-dasharray="8 5"/>';
 if(type==='river')body='<rect width="600" height="330" fill="#d7e5b5"/><path d="M95 50 Q150 90 290 160 T430 285 M420 80 Q390 150 290 160" stroke="#52a4cd" stroke-width="18" fill="none"/><path d="M360 330 L400 275 470 275 550 330" fill="#83cadd"/><text x="202" y="127">↘</text><text x="364" y="124">↙</text><text x="354" y="239">↘</text>';
 return '<svg viewBox="0 0 600 330" aria-hidden="true">'+base+body+'<text x="562" y="26" font-size="20">N ↑</text></svg>';}
function geoMap(g,i,reveal=false,study=false){const b=GEO_BOARDS[g.board],pins=g.pins||b.pins;return '<figure class="geo-map"><div class="geo-map-surface">'+(g.mapImage?'<img src="'+g.mapImage+'" alt="Teacher supplied Geography map">':geoBackdrop(b.background))+pins.map((p,n)=>study?'<span class="geo-pin geo-study" style="left:'+p[1]+'%;top:'+p[2]+'%">'+esc(p[0])+'</span>':geoButton(i,'map',String.fromCharCode(65+n),'data-value="'+n+'" class="geo-pin" style="left:'+p[1]+'%;top:'+p[2]+'%" aria-label="Map marker '+String.fromCharCode(65+n)+'"',reveal)).join('')+'</div><figcaption>'+esc(g.mapImage?'Teacher map · check orientation and scale':b.name)+'</figcaption></figure>'+(reveal?'<p>'+pins.map((p,n)=>String.fromCharCode(65+n)+': '+esc(p[0])).join(' · ')+'</p>':'');}
function geoProfile(name){const paths={'Gentle slope':'M20 130 L280 80','Steep slope':'M20 140 L280 15','Cliff':'M20 140 H140 V15 H280','U-shaped trough':'M20 20 Q60 140 105 140 H195 Q245 140 280 20','V-shaped valley':'M20 20 L150 140 L280 20','Flat plain':'M20 110 H280'};return '<svg viewBox="0 0 300 155" aria-label="'+esc(name)+'"><path d="'+(paths[name]||paths['Flat plain'])+'" fill="none" stroke="#568a71" stroke-width="12" stroke-linecap="round"/></svg>';}
function geoPanelHTML(i){const s=game.session,l=s.lanes[i],q=game.items[l.index],g=q.geo;if(l.phase==='done')return '<h2>'+esc(l.name)+' completed the trail!</h2><p>'+l.score+' points · compare your explanations with your partner.</p>';
 const locked=l.phase==='feedback'||l.phase==='locked',btn=(a,label,extra='',disabled=false)=>geoButton(i,a,label,extra,disabled);let html='<div class="geo-panel-head"><strong>'+esc(l.name)+'</strong><span>'+l.score+' points · '+(l.index+1)+' / '+game.items.length+'</span></div><div class="geo-trail">'+game.items.map((_,n)=>'<i class="'+(n<l.index?'complete':n===l.index?'current':'')+'"></i>').join('')+'</div><p class="geo-stage">'+(g.kind==='explain'?'EXPLAIN & JUSTIFY':l.index===0?'RECOGNISE':'APPLY YOUR KNOWLEDGE')+'</p><h2>'+esc(q.prompt)+'</h2>';
 if(g.kind!=='memory'||!l.studied)html+='<details class="geo-source" '+(g.kind==='choice'?'open':'')+'><summary>Evidence / practice source</summary><p>'+esc(g.source)+'</p></details>';
 if(l.phase==='feedback'){return html+'<div class="geo-feedback '+(l.good?'good':'retry')+'" role="status"><strong>'+(l.good?'Checkpoint earned!':'Learn from this checkpoint')+'</strong><p>'+esc(q.answer.replaceAll('|',' → '))+'</p><p>'+esc(q.explanation)+'</p></div>'+(['map','memory'].includes(g.kind)?'<p class="geo-map-key">'+(g.pins||GEO_BOARDS[g.board].pins).map((p,n)=>String.fromCharCode(65+n)+': '+esc(p[0])).join(' · ')+'</p>':'')+btn('next',l.index===game.items.length-1?'Finish trail →':'Next checkpoint →');}
 if(l.phase==='locked')return html+'<p>Response locked. Waiting for all teams.</p>';
 if(g.kind==='map')html+=geoMap(g,i);
 else if(g.kind==='memory'&&!l.studied)html+=geoMap(g,i,false,true)+btn('hide','I have studied it · hide map');
 else if(['choice','memory','profile'].includes(g.kind))html+='<div class="geo-choices">'+l.choices.map((a,n)=>btn('choice',(g.kind==='profile'?geoProfile(a):'')+esc(a),'data-value="'+n+'"')).join('')+'</div>';
 else if(g.kind==='order')html+='<div class="geo-sequence">'+(l.selected.length?l.selected.map(n=>'<span>'+esc(l.tiles[n].text)+'</span>').join('<b>→</b>'):'Your sequence appears here')+'</div><div class="geo-choices">'+l.tiles.map((t,n)=>btn('tile',esc(t.text),'data-value="'+n+'"',l.selected.includes(n))).join('')+'</div><div class="geo-actions">'+btn('undo','Undo','',!l.selected.length)+btn('submit','Check sequence','',l.selected.length!==l.tiles.length)+'</div>';
 else if(g.kind==='measure')html+='<div class="geo-ruler"><div style="width:'+Math.max(1,l.value/g.maximum*100)+'%"></div><strong>'+l.value+' '+esc(g.unit)+'</strong></div><div class="geo-actions">'+btn('value','−','data-value="-1"',l.value<=0)+btn('value','+','data-value="1"',l.value>=g.maximum)+btn('submit','Check measurement')+'</div>';
 else if(g.kind==='model'){const mass=Math.max(0,g.start+l.gain-l.melt);html+='<div class="geo-glacier"><div style="width:'+Math.min(100,(l.ran?mass:g.start)/30*100)+'%"></div><strong>'+(l.ran?mass:g.start)+' ice tokens</strong></div><p>Start '+g.start+' · target '+g.target+' · simplified mass-balance model</p>'+['gain','melt'].map(k=>'<div class="geo-actions"><strong>'+(k==='gain'?'❄ Accumulation':'☀ Melting')+': '+l[k]+'</strong>'+btn(k,'−','data-value="-1"',l[k]<=0)+btn(k,'+','data-value="1"',l[k]>=g.maximum)+'</div>').join('')+'<div class="geo-actions">'+btn('run','Run a year')+btn('submit','Submit model','',!l.ran)+'</div>';}
 else if(g.kind==='budget'){const cost=l.selected.reduce((a,n)=>a+g.offers[n][1],0),cover=l.selected.reduce((a,n)=>a|g.offers[n][2],0);html+='<div class="geo-needs">'+g.needs.map((n,k)=>'<span class="'+(cover&(1<<k)?'met':'')+'">'+(cover&(1<<k)?'✓ ':'○ ')+esc(n)+'</span>').join('')+'</div><strong>Tokens: '+cost+' / '+g.budget+'</strong><div class="geo-choices">'+g.offers.map((o,n)=>btn('project',esc(o[0])+' <b>'+o[1]+' tokens</b><small>'+esc(g.needs.filter((_,k)=>o[2]&(1<<k)).join(' + ')||'No listed need covered')+'</small>','data-value="'+n+'" aria-pressed="'+l.selected.includes(n)+'"')).join('')+'</div>'+btn('submit','Test this plan');}
 else if(g.kind==='explain')html+='<div class="geo-explain"><p>Explain aloud or write on your own paper. Include a claim, evidence and a reason. Teacher or partner checks your response.</p>'+(!l.reveal?btn('reveal','Ready · show model answer'):'<blockquote>'+esc(q.answer)+'</blockquote><p>Teacher / partner: does the response use accurate evidence and explain the link?</p><div class="geo-actions">'+btn('mark','Meets the criteria','data-value="1"')+btn('mark','Needs more support','data-value="0"')+'</div>')+'</div>';
 return html;
}
function geoRender(){const s=game.session;document.body.dataset.world=game.lesson.format;$('#play-title').textContent=game.lesson.title;$('#play-format').textContent=game.lesson.topic;$('#play-subtitle').textContent=GAME_MODES[s.mode].label;$('#scoreboard').innerHTML='';$('.player-bottom>span').textContent=s.mode==='TEAM'?'Lock every team response before reviewing. Rotate roles.':s.mode==='DUEL'?'Two independent touch panels · compare evidence together.':'Observe · apply · explain';
 if(game.done){const best=Math.max(...s.lanes.map(l=>l.score));$('#arena').innerHTML='<section class="geo-result"><span>🌍</span><h2>Expedition complete</h2><p>'+(s.mode==='TEAM'?esc(s.lanes.filter(l=>l.score===best).map(l=>l.name).join(' & '))+' win with '+best+' points.':s.mode==='DUEL'?'Both explorers completed the shared journey.':'You completed every checkpoint.')+'</p><div class="geo-final-scores">'+s.lanes.map(l=>'<strong>'+esc(l.name)+': '+l.score+' points</strong>').join('')+'</div><h3>Individual learning check</h3><p>Without looking back: '+esc(game.items.find(q=>q.geo.kind==='explain')?.prompt||game.items[0].prompt)+'</p><details><summary>Teacher check</summary><p>'+esc(game.items.find(q=>q.geo.kind==='explain')?.answer||game.items[0].answer)+'</p></details><button class="button primary" data-replay>Play again</button><button class="button secondary" data-edit-result>Edit lesson</button></section>';return;}
 if(s.mode==='TEAM'&&s.review){$('#arena').innerHTML='<section class="geo-result"><h2>All teams locked · compare the evidence</h2><p>'+esc(game.items[s.round].answer.replaceAll('|',' → '))+'</p><p>'+esc(game.items[s.round].explanation)+'</p><div class="geo-final-scores">'+s.lanes.map(l=>'<strong>'+esc(l.name)+': '+(l.good?'✓ +100':'Review needed')+' · '+l.score+' total</strong>').join('')+'</div>'+geoButton(0,'team-next',s.round===game.items.length-1?'Finish expedition →':'Next checkpoint →')+'</section>';return;}
 $('#arena').className='arena geo-arena';$('#arena').innerHTML=(s.mode==='TEAM'?'<div class="geo-team-tabs">'+s.lanes.map((l,i)=>'<span class="'+(s.active===i?'active':'')+'">'+esc(l.name)+(l.phase==='locked'?' 🔒':'')+'</span>').join('')+'</div>':'')+'<div class="geo-panels '+(s.mode==='DUEL'?'geo-dual':'')+'">'+(s.mode==='DUEL'?[0,1]:[s.mode==='TEAM'?s.active:0]).map(i=>'<section class="geo-panel" data-geo-panel="'+i+'">'+geoPanelHTML(i)+'</section>').join('')+'</div>';}
function geoPaint(i){if(game.session.mode==='DUEL'){const p=document.querySelector('[data-geo-panel="'+i+'"]');if(p)p.innerHTML=geoPanelHTML(i);}else geoRender();}
function geoScore(i,good){const s=game.session,l=s.lanes[i];if(l.phase!=='question')return;l.good=good;l.correct+=good?1:0;l.score+=good?100:0;l.history.push({index:l.index,good});game.attempts++;game.correct+=good?1:0;game.score+=good?100:0;l.phase=s.mode==='TEAM'?'locked':'feedback';if(s.mode==='TEAM'){const next=s.lanes.findIndex(x=>x.phase==='question');if(next<0)s.review=true;else s.active=next;geoRender();}else geoPaint(i);}
function geoHandle(b){const s=game.session,i=Number(b.dataset.lane),l=s.lanes[i],a=b.dataset.modeAction.slice(4),n=Number(b.dataset.value);if(!l||game.done||ui.view!=='player'||b.disabled)return;if(s.mode==='TEAM'&&!s.review&&i!==s.active)return;
 if(a==='team-next'&&s.mode==='TEAM'&&s.review){s.round++;if(s.round>=game.items.length){game.done=true;geoRender();return;}s.review=false;s.active=0;s.lanes.forEach(x=>{x.index=s.round;geoRound(x);});geoRender();return;}
 if(a==='next'&&l.phase==='feedback'){l.index++;if(l.index>=game.items.length){l.index=game.items.length-1;l.phase='done';}else geoRound(l);if(s.lanes.every(x=>x.phase==='done')){game.done=true;geoRender();}else geoPaint(i);return;}
 if(l.phase!=='question'||s.review)return;const q=game.items[l.index],g=q.geo;
 if(a==='choice'&&['choice','memory','profile'].includes(g.kind)&&!(g.kind==='memory'&&!l.studied)&&Number.isInteger(n)&&l.choices[n]!==undefined){geoScore(i,l.choices[n]===q.answer);return;}
 if(a==='map'&&g.kind==='map'){const p=(g.pins||GEO_BOARDS[g.board].pins)[n];if(p)geoScore(i,p[0]===q.answer);return;}
 if(a==='tile'&&g.kind==='order'&&l.tiles[n]&&!l.selected.includes(n))l.selected.push(n);else if(a==='undo'&&g.kind==='order')l.selected.pop();
 else if(a==='project'&&g.kind==='budget'&&g.offers[n])l.selected=l.selected.includes(n)?l.selected.filter(x=>x!==n):[...l.selected,n];
 else if(a==='value'&&g.kind==='measure'&&[-1,1].includes(n))l.value=Math.max(0,Math.min(g.maximum,l.value+n));
 else if(['gain','melt'].includes(a)&&g.kind==='model'&&[-1,1].includes(n)){l[a]=Math.max(0,Math.min(g.maximum,l[a]+n));l.ran=false;}
 else if(a==='run'&&g.kind==='model')l.ran=true;
 else if(a==='hide'&&g.kind==='memory')l.studied=true;
 else if(a==='reveal'&&g.kind==='explain')l.reveal=true;
 else if(a==='mark'&&g.kind==='explain'&&l.reveal&&[0,1].includes(n)){geoScore(i,n===1);return;}
 else if(a==='submit'){let good;if(g.kind==='order'&&l.selected.length===l.tiles.length)good=l.selected.every((v,k)=>l.tiles[v].id===k);else if(g.kind==='measure')good=l.value===Number(q.answer);else if(g.kind==='model'&&l.ran)good=Math.max(0,g.start+l.gain-l.melt)===g.target;else if(g.kind==='budget')good=l.selected.reduce((v,k)=>v+g.offers[k][1],0)<=g.budget&&l.selected.reduce((v,k)=>v|g.offers[k][2],0)===7;else return;geoScore(i,good);return;}else return;
 geoPaint(i);
}
// Touch acts immediately and only repaints its own player's panel, preserving the other finger's target.
document.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-mode-action^="geo-"]');if(b&&e.pointerType==='touch'){e.preventDefault();geoHandle(b);}},{passive:false});
function geoSetup(host){const index=GEO_PACKS.findIndex(p=>p.id===draft.id),topic=index>=0?GEO_PLAN[Math.floor(index/2)]:null,idea=index>=0?topic.games[index%2]:null;host.insertAdjacentHTML('beforeend','<div class="geo-adaptation"><strong>Smartboard Geography · three checkpoints</strong><p>Recognise → apply → explain, followed by an individual learning check. Maps are schematic; token costs and practice datasets are simplified classroom examples.</p>'+(idea?'<details><summary>Original idea and digital adaptation</summary><p>'+esc(idea.idea)+'</p><p>This board version uses '+esc(draft.items.map(q=>q.geo?.kind||'choice').join(', '))+' challenges. Photograph descriptions, physical models and extended writing become on-screen evidence, interactive tasks and spoken/paper responses. Review the source below before teaching.</p></details>':'')+'<p><a href="./geography-guide.html" target="_blank" rel="noopener">Teacher guide, all 116 adaptations and source notes ↗</a></p></div>');}
document.addEventListener('DOMContentLoaded',()=>{const b=document.createElement('button');b.id='geo-browse';b.className='button secondary geo-browse';b.textContent='Explore Geography · 116 activities →';document.querySelector('#lab-browse').after(b);b.onclick=()=>{ui.collection='library';ui.grade='all';ui.subject='geography';ui.search='';ui.players='all';$('#search').value='';renderLibrary();$('#library-title').scrollIntoView({behavior:'smooth'});};if(new URLSearchParams(location.search).get('subject')==='geography'&&!new URLSearchParams(location.search).has('game'))b.click();const original=window.render_game_to_text;window.render_game_to_text=()=>{if(!game?.session?.geography||ui.view!=='player')return original();const s=game.session;return JSON.stringify({view:game.done?'result':'playing',format:game.lesson.format,mode:s.mode,lesson:game.lesson.title,round:s.round,review:s.review,score:game.score,activeTeam:s.active,players:s.lanes.map(l=>({name:l.name,index:l.index,score:l.score,phase:l.phase,prompt:game.items[l.index].prompt,kind:game.items[l.index].geo.kind,choices:l.phase==='question'?l.choices:[],selected:l.selected,measurement:l.value,accumulation:l.gain,melting:l.melt,modelRun:l.ran,feedback:l.good})),coordinateSystem:'Maps use percentages: x increases right; y increases down. North is up. Grid references use eastings then northings.'});};});
